write('tactour.htm','Community Development Tour','Photographs of the March 11, 2004 community development tour at Concord at Allendale.',intro('A closer look at community development.','March 11, 2004 · Concord at Allendale')+'<section class="wrap"><div class="prose"><p>The Texas Association community development tour brought visitors to Concord at Allendale to see the development and meet with the community.</p></div><div class="gallery">'+gallery+'</div></section>','News')
write('Public Meeting.htm','Las Villas Public Meeting','A January 2004 neighborhood meeting about the proposed Las Villas De Magnolia development.',intro('A conversation with future neighbors.','January 2004 · Las Villas De Magnolia')+'<section class="wrap"><div class="prose"><p>AAMA-CDC hosted a public meeting over coffee to discuss plans for a proposed 116-unit senior housing development at Harrisburg and 72nd Streets.</p><p><a class="text-link" href="magnolia.wmv" download>Download the original meeting video (WMV)</a></p></div><div class="gallery">'+''.join(image('images/'+f,'Neighbors discussing the original Las Villas De Magnolia proposal') for f in ['mDscf1529.jpg','mDscf1533.jpg','mDscf1536.jpg'])+'</div></section>','News')
write('newsflash.htm','Concord Ribbon Cutting','The December 2003 ribbon cutting at Concord at Allendale.',intro('Welcoming Concord at Allendale.','December 17, 2003 · Community archive')+'<section class="wrap detail-layout"><div class="prose"><p>AAMA-CDC celebrated the ribbon cutting for Concord at Allendale, a 264-home affordable housing development created in partnership with Trammel Crow Residential.</p><p>The initiative was designed to help families access attractive housing while lowering their housing costs.</p>'+link('concord.htm','Explore Concord at Allendale')+'</div><figure>'+image('TAC/images/Dscf9359a.jpg','Balloons at the entrance of Concord at Allendale')+'</figure></section>','News')

# Preserve the original resource destinations and labels, grouped for readability.
# These are historical partnerships, not claims about current affiliations.
import re
original_links = ROOT/'scripts'/'original-links.txt'
if not original_links.exists():
    source=(ROOT/'aamacdclinks.htm').read_text(encoding='latin1')
    items=[]
    for url,label in re.findall(r'<a\s+href="(https?://[^\"]+)"[^>]*>(.*?)</a>',source,re.S|re.I):
        label=' '.join(re.sub('<[^>]+>',' ',label).split())
        if label: items.append((url,label))
    original_links.write_text('\n'.join(url+'\t'+label for url,label in items),encoding='utf-8')
items=[line.split('\t',1) for line in original_links.read_text().splitlines() if '\t' in line and not line.startswith('http://al-fin.com/')]
resources=intro('Links','Financial, community, and development organizations referenced in our original project history.')+'<section class="wrap"><p class="archive-note">This directory preserves historical partner references. Organizations and web addresses may have changed since the original projects.</p><div class="resource-list">'
for label,start,end in [('Financial partners',0,6),('Community partners',6,11),('Development partners',11,len(items))]:
    unlinked = {'Community partners': '<p>La Rosa of Houston</p>', 'Development partners': '<p>Whitney Management/Whitney Capital</p>'}.get(label, '')
    resources+=f'<div><h2>{label}</h2>'+''.join(f'<p><a href="{escape(u,quote=True)}">{l}</a></p>' for u,l in items[start:end])+unlinked+'</div>'
resources+='</div></section>'
write('aamacdclinks.htm','Links','Historical financial, community, and development partner resources.',resources)

def redirect(name, target):
    path=ROOT/name
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><meta http-equiv="refresh" content="0;url={target}"><title>AAMA-CDC</title></head><body><p>This page has moved. <a href="{target}">Continue to AAMA-CDC</a>.</p></body></html>\n',encoding='utf-8')

# Retire the board and former individual profiles, including direct bookmarked URLs.
redirects={'board.htm':'staff.htm','board518.htm':'staff.htm','santos.htm':'staff.htm','gary.htm':'staff.htm','carlosalvarez.htm':'staff.htm','intro.htm':'index.html','tactour2.htm':'tactour.htm','mediaISDN.htm':'concord.htm','mediamed.htm':'concord.htm','medialarge.htm':'concord.htm','mediaplazademagniteout.htm':'NationalNightOut.htm','nclrphoenix/nclrphoenix.htm':'../news.htm'}
for name,target in redirects.items(): redirect(name,target)
# Old public backup URLs must not reintroduce retired member or board information.
for folder in ['backup','bak','tmp']:
    for path in (ROOT/folder).glob('*'):
        if path.suffix.lower() in ['.htm','.html']:
            target=redirects.get(path.name,path.name)
            if not (ROOT/target).exists(): target='index.html'
            redirect(str(path.relative_to(ROOT)),'../'+target.replace(' ','%20'))
print('Generated modern pages and legacy redirects.')
